/**
 * HTML renderer style variables
 */
export class ViewportCssVariableNames {
    /**All content container width*/
    static readonly ContentsContainerWidth = "--contents-container-width";
    static readonly ContentsContainerOffsetLeft = "--contents-container-offsetleft";
    /**All content container spacing */
    static readonly ContentsContainerPadding = "--contents-container-padding";

    static readonly ScrollElementOverflow = "--scroll-element-overflow";
    static readonly ScrollElementVerticalScrollBarWidth = "--scroll-element-vertial-scrollbar-width";
    static readonly ScrollElementHorizontalScrollBarHeight = "--scroll-element-horizontal-scrollbar-height";

    /**Each content wrapper container width*/
    static readonly ContentWrapperWidth = "--content-wrapper-width";
    /**Each content wrapper container minimum width*/
    static readonly ContentWrapperMinWidth = "--content-wrapper-min-width";
    /**Each content wrapper container height*/
    static readonly ContentWrapperHeight = "--content-wrapper-height";
    /**Each content wrapper container padding */
    static readonly ContentWrapperPadding = "--content-wrapper-padding";
    /**Initial content wrapper container minimum height */
    static readonly ContentWrapperMinHeight = "--content-wrapper-min-height";
    /**Initial content wrapper container maximum height */
    static readonly ContentWrapperMaxHeight = "--content-wrapper-max-height";
    
    /**Each content wrapper container top spacing */
    static readonly ContentWrapperMarginTop = "--content-wrapper-margin-top";
    /**Each content wrapper container bottom spacing */
    static readonly ContentWrapperMarginBottom = "--content-wrapper-margin-bottom";
    /**Each content wrapper container corner radius */
    static readonly ContentWrapperBorderRadius = "--content-wrapper-border-radius";

    /**Each content container default width */
    static readonly ContentContainerWidth = "--content-container-width";
    /**Each content container default height */
    static readonly ContentContainerHeight = "--content-container-height";
    /**Column spacing */
    static readonly ContentColumnGap = "--content-column-gap";
    /**Column rule width */
    static readonly ContentColumnRuleWidth = "--content-column-rule-width";
}
